// 反序列化时各类成员的命运：
class Foo implements Serializable {
  int a = 10;                    // 非 transient：从流里读回存时的值（构造器不跑）
  transient int b = 20;          // transient：构造器不跑 → 保持默认值 0，不是 20
  transient String s = "hi";     // transient 引用：null，不是 "hi"
  static int count = 5;          // static：取当前类的值，不参与序列化
}
// 若 Foo 的父类 Bar 不可序列化：反序列化时 Bar 的构造器会跑，并连锁调用其父类构造器

import java.io.*;

// 演示「链」的概念：对象 → ObjectOutputStream → FileOutputStream → 文件
public class ChainDemo {
  public static void main(String[] args) throws IOException {
    // 连接流：它的职责只有一件——连到文件并写字节
    FileOutputStream connection = new FileOutputStream("demo.ser");
    // 链流：它的职责也只有一件——把对象变成可写的字节数据
    ObjectOutputStream chain = new ObjectOutputStream(connection);
    // 我们只对链流下命令，连接流在底下默默配合
    chain.writeObject("一个字符串对象");
    // 关掉顶层即可，链底下的连接流会被自动关闭
    chain.close();
  }
}

