import java.io.*;

public class WriteSerialized {
  public static void main(String[] args) {
    try {
      // 第一步：造一条连接流，连到文件；文件不存在就自动创建
      FileOutputStream fileStream = new FileOutputStream("MyGame.ser");
      // 第二步：造一条链流，挂到连接流上
      ObjectOutputStream os = new ObjectOutputStream(fileStream);
      // 第三步：按顺序写三个对象，不需要碰底下的 fileStream
      os.writeObject(characterOne);
      os.writeObject(characterTwo);
      os.writeObject(characterThree);
      // 第四步：关最上层，整条链连同文件一起关闭
      os.close();
    } catch (IOException ex) {   // I/O 随时可能出问题，必须处理异常
      ex.printStackTrace();
    }
  }
}

// 序列化心智模型一图流（用注释表示流水线）：
//   对象 --[Serializable 许可]--> ObjectOutputStream[压平]
//        --> FileOutputStream[卡车] --> 文件
//   读：文件 --> FileInputStream --> ObjectInputStream[充气] --> 强转 --> 对象
//   全程：对象图递归、transient 跳过、static 不存、版本号对齐、读写顺序一致

// 保存：把 256 个复选框状态压成一个 boolean 数组序列化出去
private void writeFile() {
  boolean[] checkboxState = new boolean[256];
  for (int i = 0; i < 256; i++) {
    if (checkboxList.get(i).isSelected()) checkboxState[i] = true;
  }
  try (ObjectOutputStream os =
         new ObjectOutputStream(new FileOutputStream("Checkbox.ser"))) {
    os.writeObject(checkboxState);
  } catch (IOException e) { e.printStackTrace(); }
}

// 还原：读回来强转成 boolean[]，再逐个设置复选框
private void readFile() {
  boolean[] checkboxState = null;
  try (ObjectInputStream is =
         new ObjectInputStream(new FileInputStream("Checkbox.ser"))) {
    checkboxState = (boolean[]) is.readObject();
  } catch (Exception e) { e.printStackTrace(); }
  for (int i = 0; i < 256; i++) checkboxList.get(i).setSelected(checkboxState[i]);
  sequencer.stop();
  buildTrackAndStart();
}

